/**
 * One-off probe (not part of the app): measures the thinking-block layout in a
 * headless browser via the Chrome DevTools Protocol.
 *
 * It loads probe-output/thinking-layout.html (generated by thinking-layout.mjs
 * from the real dobao-front/src/style.css + real marked config) and reports,
 * for both the pre-fix and post-fix panels, the height of the thinking block
 * and the vertical gaps between adjacent list items.
 *
 * Usage: node probe-output/thinking-layout-measure.mjs <cdpPort> <pageUrl>
 */
const port = process.argv[2] || '9222'
const pageUrl = process.argv[3]

const listTargets = async () => {
  const res = await fetch(`http://127.0.0.1:${port}/json/list`)
  return res.json()
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

// wait for the browser to expose the page we asked it to open, loaded
let target = null
for (let i = 0; i < 60; i++) {
  try {
    const targets = await listTargets()
    target = targets.find((t) => t.type === 'page' && t.url.includes('thinking-layout.html'))
    if (target && target.webSocketDebuggerUrl) break
  } catch {
    // browser not up yet
  }
  await sleep(250)
}
if (!target) {
  console.error('FAIL: could not find the probe page in CDP target list')
  process.exit(1)
}

const ws = new WebSocket(target.webSocketDebuggerUrl)
await new Promise((resolve, reject) => {
  ws.onopen = resolve
  ws.onerror = reject
})

let nextId = 1
const pending = new Map()
ws.onmessage = (event) => {
  const msg = JSON.parse(event.data)
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg)
    pending.delete(msg.id)
  }
}

const send = (method, params = {}) =>
  new Promise((resolve) => {
    const id = nextId++
    pending.set(id, resolve)
    ws.send(JSON.stringify({ id, method, params }))
  })

await send('Runtime.enable')
// give layout a moment after load
await sleep(500)

const expression = `(() => {
  const measure = (id) => {
    const root = document.getElementById(id);
    if (!root) return { error: 'missing #' + id };
    const items = [...root.querySelectorAll('ol > li')];
    const gaps = [];
    for (let i = 1; i < items.length; i++) {
      gaps.push(Math.round((items[i].getBoundingClientRect().top - items[i-1].getBoundingClientRect().bottom) * 10) / 10);
    }
    const blocks = [...root.children].map((el) => {
      const r = el.getBoundingClientRect();
      return { tag: el.tagName, h: Math.round(r.height * 10) / 10, top: Math.round(r.top * 10) / 10, bottom: Math.round(r.bottom * 10) / 10 };
    });
    const self = root.getBoundingClientRect();
    return {
      whiteSpace: getComputedStyle(root).whiteSpace,
      listItems: items.length,
      looseItems: root.querySelectorAll('ol > li > p').length,
      gapsBetweenItems_px: gaps,
      blockHeights: blocks,
      blockGaps_px: blocks.slice(1).map((b, i) => Math.round((b.top - blocks[i].bottom) * 10) / 10),
      thinkingBlockHeight_px: Math.round(self.height * 10) / 10,
      htmlHasNewlines: /\\n/.test(root.innerHTML)
    };
  };
  return JSON.stringify({ current: measure('current'), fixed: measure('fixed'), fixedNorm: measure('fixedNorm') }, null, 2);
})()`

const result = await send('Runtime.evaluate', { expression, returnByValue: true })
if (result.result?.exceptionDetails) {
  console.error('FAIL: evaluate threw', JSON.stringify(result.result.exceptionDetails))
  process.exit(1)
}
console.log(result.result.result.value)
ws.close()
